import { readdir, readFile, mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';

/**
 * The bundled workflow templates, discovered the way the capsules are: one folder per template, one
 * manifest, and one generated file nobody edits. This replaced a hand-written map in
 * `server/templates.ts`, where adding a template meant editing code and the file's path was a string
 * that nothing checked. Now adding a template is adding its folder, and a folder that is not a
 * template fails here instead of at request time.
 *
 * A template owns everything it needs: `workflow.json` (the graph the gallery opens), `thumbnail.svg`
 * (the card art) and the build script that writes the workflow from its scene designs. The manifest
 * carries only what the card shows — the folder name is the id.
 */

const root = process.cwd();
const templatesDir = path.join(root, 'templates');
const generatedDir = path.join(templatesDir, '.generated');

const WORKFLOW = 'workflow.json';
const THUMBNAIL = 'thumbnail.png';

const folders = (await readdir(templatesDir, { withFileTypes: true }))
  .filter((entry) => entry.isDirectory() && !entry.name.startsWith('.') && !entry.name.startsWith('_'))
  .map((entry) => entry.name)
  .sort();

/** `LocalizedText` is a plain string or a locale map; a typo in either shape is worth failing on. */
function isLocalized(value) {
  if (typeof value === 'string') return value.length > 0;
  return typeof value === 'object' && value !== null && !Array.isArray(value) && Object.values(value).every((text) => typeof text === 'string' && text.length > 0);
}

const templates = [];
for (const folder of folders) {
  const file = path.join(templatesDir, folder, 'template.manifest.json');
  let manifest;
  try {
    manifest = JSON.parse(await readFile(file, 'utf8'));
  } catch (error) {
    // A folder inside `templates/` is a template or it is a mistake. Unlike a capsule folder there is
    // no shared-file exception to tolerate, so a missing manifest is an error and not a skip.
    throw new Error(`templates/${folder}: ${error.code === 'ENOENT' ? 'template.manifest.json is missing' : `template.manifest.json is not readable (${error.message})`}`);
  }
  const fail = (why) => {
    throw new Error(`templates/${folder}/template.manifest.json: ${why}`);
  };
  if (typeof manifest.id !== 'string' || !manifest.id) fail('id is required');
  if (manifest.id !== folder) fail(`id "${manifest.id}" must match the folder name`);
  if (manifest.group !== 'video') fail('group must be "video"');
  if (!isLocalized(manifest.tagline)) fail('tagline must be a string or a locale map');
  if (manifest.tags !== undefined && (!Array.isArray(manifest.tags) || !manifest.tags.every(isLocalized))) fail('tags must be an array of strings or locale maps');
  if (manifest.thumbnail !== undefined && (typeof manifest.thumbnail !== 'string' || !manifest.thumbnail)) fail('thumbnail must be a file name');
  templates.push({
    id: manifest.id,
    group: manifest.group,
    tagline: manifest.tagline,
    tags: manifest.tags ?? [],
    workflow: WORKFLOW,
    thumbnail: manifest.thumbnail ?? THUMBNAIL,
  });
}

const generated = `/* Generated by scripts/discover-templates.mjs. Do not edit. */
import type { LocalizedText } from '@/core/engine/document';

/** What the gallery card shows, and which files the template's own folder holds. */
export type TemplateDescriptor = {
  id: string;
  group: 'video';
  tagline: LocalizedText;
  tags: LocalizedText[];
  /** File inside \`templates/<id>/\` holding the graph the gallery opens. */
  workflow: string;
  /** File inside \`templates/<id>/\` holding the card art. */
  thumbnail: string;
};

/**
 * Every template this build ships. The id is the folder that owns it, so a template is added, moved
 * or removed by moving one folder — never by editing this list.
 */
export const TEMPLATES: TemplateDescriptor[] = [
${templates.map((template) => `  { id: '${template.id}', group: '${template.group}', tagline: ${JSON.stringify(template.tagline)}, tags: ${JSON.stringify(template.tags)}, workflow: '${template.workflow}', thumbnail: '${template.thumbnail}' },`).join('\n')}
];
`;

await mkdir(generatedDir, { recursive: true });
await writeFile(path.join(generatedDir, 'descriptors.ts'), generated);
console.log(`Discovered ${templates.length} workflow template${templates.length === 1 ? '' : 's'}.`);
